    enrollments[enrollment_id] = {"id": enrollment_id, "child_id": child_id, "classroom_id": classroom_id, "status": "enrolled"}
    classroom["enrolled_child_ids"].append(child_id)
    return jsonify(enrollments[enrollment_id]), 201


